package ru.ryadom.calendar;
import android.os.Build;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.*;import org.junit.runner.RunWith;import org.json.*;import okhttp3.*;import okio.Buffer;import java.util.*;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class)
public class NetworkWriteTest {
 OkHttpClient original;List<String> requests=new ArrayList<>();
 @Before public void begin(){assertTrue(Build.HARDWARE.equals("ranchu")||Build.HARDWARE.equals("goldfish"));original=Providers.HTTP;}
 @After public void end(){Providers.HTTP=original;}
 Response response(Request request,int status,String body,String etag){return new Response.Builder().request(request).protocol(Protocol.HTTP_1_1).code(status).message("Fixture").header("ETag",etag).body(ResponseBody.create(body,MediaType.get("text/xml"))).build();}
 JSONObject account(String type)throws Exception{return new JSONObject().put("id","fixture").put("type",type).put("endpoint","https://calendar.example.test/EWS/Exchange.asmx").put("login","demo@example.test").put("password","fixture-only");}
 String xml(String content){return EventWrites.envelope(content);}
 String success(String id){return xml("<m:ResponseCode>NoError</m:ResponseCode>"+(id.isEmpty()?"":"<t:CalendarItem><t:ItemId Id=\""+id+"\" ChangeKey=\"v1\"/></t:CalendarItem>"));}
 Event event(){Event e=new Event();e.source="fixture";e.calendar="main";e.title="Тест < & >";e.description="Только тест";e.start=1800000000000L;e.end=e.start+3600000;e.reminderMinutes=37;return e;}
 @Test public void ewsRecoveryEscapingAndConflict()throws Exception{
  final boolean[] created={false};Providers.HTTP=new OkHttpClient.Builder().addInterceptor(chain->{Request req=chain.request();Buffer out=new Buffer();req.body().writeTo(out);String body=out.readUtf8();requests.add(body);assertFalse(req.url().toString().contains("password"));if(body.contains("<m:FindItem")){assertTrue(body.contains("PekloToken"));return response(req,200,success(created[0]?"fixture-id":""),"");}if(body.contains("<m:CreateItem")){created[0]=true;assertEquals("\""+Providers.M+"/CreateItem\"",req.header("SOAPAction"));assertTrue(body.contains("SendToNone"));assertTrue(body.contains("&lt; &amp; &gt;"));assertTrue(body.contains("<t:ReminderMinutesBeforeStart>37</t:ReminderMinutesBeforeStart>"));assertFalse(body.contains("Attendees"));return response(req,200,success("fixture-id"),"");}assertTrue(body.contains("<m:UpdateItem"));assertTrue(body.contains("NeverOverwrite"));assertTrue(body.contains("ChangeKey=\"v1\""));return response(req,200,success("fixture-id"),"");}).build();
  Event e=event();android.content.Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();EventWrites.save(c,account("ews"),"main",null,e,"copy-fixture");EventWrites.save(c,account("ews"),"main",null,e,"copy-fixture");assertEquals(1,requests.stream().filter(r->r.contains("<m:CreateItem")).count());
  Providers.HTTP=new OkHttpClient.Builder().addInterceptor(chain->response(chain.request(),200,xml("<m:ResponseCode>ErrorIrresolvableConflict</m:ResponseCode>"),"")).build();try{EventWrites.save(c,account("ews"),"main",null,e,"copy-fixture");fail();}catch(Providers.Failure expected){assertTrue(expected.getMessage().contains("ErrorIrresolvableConflict"));}
 }
 @Test public void caldavConditionalSavePreservesOtherFields()throws Exception{
  final String[] raw={null};final int[] puts={0};Providers.HTTP=new OkHttpClient.Builder().addInterceptor(chain->{Request req=chain.request();if(req.method().equals("GET"))return response(req,raw[0]==null?404:200,raw[0]==null?"":raw[0],"v"+puts[0]);assertEquals("PUT",req.method());if(puts[0]==0)assertEquals("*",req.header("If-None-Match"));else assertEquals("v"+puts[0],req.header("If-Match"));Buffer out=new Buffer();req.body().writeTo(out);raw[0]=out.readUtf8();puts[0]++;return response(req,201,"","v"+puts[0]);}).build();Event e=event();JSONObject a=account("yandex");String cal="https://caldav.yandex.ru/calendars/fixture/";Event saved=DavWrites.save(a,cal,null,e,"edit-fixture");assertEquals(-37*60000L,biweekly.Biweekly.parse(raw[0]).first().getEvents().get(0).getAlarms().get(0).getTrigger().getDuration().toMillis());assertEquals(e.title,biweekly.Biweekly.parse(raw[0]).first().getEvents().get(0).getSummary().getValue());e.reminderMinutes=-1;e.title="Обновлено";DavWrites.save(a,cal,saved,e,"edit-fixture");assertFalse(raw[0].contains("VALARM"));assertEquals(1,biweekly.Biweekly.parse(raw[0]).first().getEvents().size());assertEquals(-1,Providers.parseIcs(raw[0],"fixture",cal,e.start-1,e.end+1).get(0).reminderMinutes);
  // A retry after an uncertain initial response reuses the same resource.
  DavWrites.save(a,cal,null,e,"edit-fixture");assertEquals(3,puts[0]);assertTrue(raw[0].contains("UID:peklo-edit-fixture"));
 }
}
